<?php
require_once __DIR__.'/bootstrap.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: filter_input(INPUT_GET,'anime_id',FILTER_VALIDATE_INT) ?: 0;
$requestedEpisode=(float)($_GET['episode']??$_GET['ep']??1);$requestedLanguage=trim((string)($_GET['language']??$_GET['lang']??''));$requestedServer=trim((string)($_GET['server']??''));
$s=$pdo->prepare('SELECT * FROM anime WHERE id=?');$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Anime not found');}
$es=$pdo->prepare('SELECT * FROM episodes WHERE anime_id=? AND active=1 ORDER BY number');$es->execute([$id]);$episodes=$es->fetchAll();$episode=$episodes[0]??null;foreach($episodes as $candidate){if((float)$candidate['number']===$requestedEpisode){$episode=$candidate;break;}}
$sources=[];$languages=[];$selectedLanguage='';$current=null;$filtered=[];
if($episode){$vs=$pdo->prepare('SELECT * FROM video_sources WHERE anime_id=? AND episode_id=? AND active=1 ORDER BY priority ASC,server_name ASC');$vs->execute([$id,$episode['id']]);$sources=$vs->fetchAll();$languages=array_values(array_unique(array_column($sources,'language')));$selectedLanguage=in_array($requestedLanguage,$languages,true)?$requestedLanguage:($languages[0]??'');$filtered=array_values(array_filter($sources,fn($source)=>(string)$source['language']===$selectedLanguage));$current=$filtered[0]??null;if($requestedServer!==''){foreach($filtered as $source){if($source['server_name']===$requestedServer){$current=$source;break;}}}}
$index=-1;foreach($episodes as $key=>$item){if($episode&&$item['id']===$episode['id']){$index=$key;break;}}$previous=$index>0?$episodes[$index-1]:null;$next=($index>=0&&isset($episodes[$index+1]))?$episodes[$index+1]:null;
$title='Watch '.($a['title']??'Anime').' — AniRead';$description='Watch '.($a['title']??'anime').' episode '.($episode['number']??$requestedEpisode).' with authorized sources on AniRead.';include __DIR__.'/includes/header.php';
?><div class="watch-shell"><div class="watch-main"><div class="watch-heading"><div><a class="back-link" href="<?=url('anime.php?id='.$id)?>">← Back to details</a><h1><?=e($a['title'])?></h1><p class="muted">Episode <?=e($episode['number']??$requestedEpisode)?><?=!empty($episode['title'])?' · '.e($episode['title']):''?></p></div><label class="auto-next"><input id="auto-next" type="checkbox" checked> Auto next</label></div><?php if($current):?><div class="player player-wide"><?php if($current['source_type']==='iframe'):?><iframe src="<?=e($current['source_url'])?>" title="<?=e($a['title'])?> video player" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe><?php else:?><video id="video" controls autoplay playsinline preload="metadata"><source src="<?=e($current['source_url'])?>" type="<?=$current['source_type']==='hls'?'application/vnd.apple.mpegurl':'video/mp4'?>">Your browser cannot play this video source.</video><?php endif;?></div><?php else:?><div class="unavailable"><strong>Streaming source unavailable for this episode.</strong><span>An administrator must configure an active authorized source before playback is available.</span></div><?php endif;?><div class="watch-controls"><?php if($previous):?><a class="btn alt" href="<?=url('watch.php?id='.$id.'&episode='.urlencode($previous['number']).($selectedLanguage?'&lang='.rawurlencode($selectedLanguage):''))?>">← Previous</a><?php else:?><span></span><?php endif;if($next):?><a class="btn" id="next-episode" href="<?=url('watch.php?id='.$id.'&episode='.urlencode($next['number']).($selectedLanguage?'&lang='.rawurlencode($selectedLanguage):''))?>">Next →</a><?php endif;?></div></div><aside class="watch-side"><h2>Episodes</h2><div class="episode-list episode-scroll"><?php foreach($episodes as $item):?><a class="<?=($episode&&$item['id']===$episode['id'])?'current':''?>" href="<?=url('watch.php?id='.$id.'&episode='.urlencode($item['number']).($selectedLanguage?'&lang='.rawurlencode($selectedLanguage):''))?>">Episode <?=e($item['number'])?></a><?php endforeach;?></div><?php if($languages):?><h2 class="selector-title">Language</h2><div class="source-tabs"><?php foreach($languages as $language):?><a class="<?=selected($language,$selectedLanguage)?>" href="<?=url('watch.php?id='.$id.'&episode='.urlencode($episode['number']).'&lang='.rawurlencode($language))?>"><?=e($language)?></a><?php endforeach;?></div><h2 class="selector-title">Servers</h2><div class="source-tabs"><?php foreach($filtered as $source):?><a class="<?=($current&&$source['id']===$current['id'])?'selected':''?>" href="<?=url('watch.php?id='.$id.'&episode='.urlencode($episode['number']).'&lang='.rawurlencode($selectedLanguage).'&server='.rawurlencode($source['server_name']))?>"><?=e($source['server_name'])?></a><?php endforeach;?></div><?php else:?><p class="muted">No language or server is available for this episode.</p><?php endif;?></aside></div><script>(function(){const checkbox=document.getElementById('auto-next'),video=document.getElementById('video'),next=document.getElementById('next-episode');checkbox.checked=localStorage.getItem('anireadAutoNext')!=='0';checkbox.addEventListener('change',()=>localStorage.setItem('anireadAutoNext',checkbox.checked?'1':'0'));if(video&&next)video.addEventListener('ended',()=>{if(checkbox.checked)window.location.href=next.href;});})();</script><?php if(user()&&$episode){$h=$pdo->prepare('INSERT INTO watch_history(user_id,anime_id,episode_number,updated_at) VALUES(?,?,?,NOW()) ON DUPLICATE KEY UPDATE episode_number=VALUES(episode_number),updated_at=NOW()');$h->execute([user()['id'],$id,$episode['number']]);}include __DIR__.'/includes/footer.php';
